#!/usr/bin/env python3
"""Focused security regression harness for the doGetChar() setter-callback fix.

This harness does NOT reimplement the logic under test. It reads the real
runtime/cfsysline.c from the checkout passed via --source, extracts the
doGetChar() function verbatim (brace-matched), and compiles it together with
stub definitions and a recording handler that emulates the real setter
setParserControlCharacterEscapePrefix() (which dereferences its second
argument).

Expected behaviours:
  * fixed  : the setter callback receives a valid pointer to the current
             configuration character (== *pp), dereferences to that character,
             and *pp advances by one.
  * buggy  : the setter callback receives the integer value of the character
             cast to a pointer (e.g. 0x41 for 'A'), which is not a valid
             pointer; the harness detects this without dereferencing it.

Exit code 0 iff observed behaviour matches --expect.
"""
from __future__ import annotations

import argparse
import re
import subprocess
import sys
import tempfile
from pathlib import Path

SIG_RE = re.compile(
    r"static\s+rsRetVal\s+doGetChar\(\s*uchar\s*\*\*pp\s*,\s*"
    r"rsRetVal\s*\(\*pSetHdlr\)\s*\(\s*void\s*\*\s*,\s*([^)]+?)\s*\)\s*,"
)

PRELUDE = r"""
#include <stdio.h>
#include <stdint.h>
#include <string.h>

typedef int rsRetVal;
typedef unsigned char uchar;
typedef unsigned int uid_t;

#define RS_RET_OK 0
#define RS_RET_NOT_FOUND 1
#define DEFiRet rsRetVal iRet = RS_RET_OK
#define RETiRet return iRet
#define CHKiRet(op) do { iRet = (op); if (iRet != RS_RET_OK) goto finalize_it; } while (0)

static void skipWhiteSpace(uchar **pp)
{
    while (**pp == ' ' || **pp == '\t' || **pp == '\n' || **pp == '\r')
        ++(*pp);
}

static void LogError(int i, rsRetVal r, const char *fmt, ...)
{
    (void)i; (void)r; (void)fmt;
}

/* ---- verbatim doGetChar() extracted from target runtime/cfsysline.c ---- */
"""

EPILOGUE = r"""
/* ----------------------------------------------------------------------- */

static int g_called = 0;
static uchar *g_ptr = NULL;
static uchar g_char = 0;
static int g_invalid_ptr = 0;

/* Emulates setParserControlCharacterEscapePrefix(void*, uchar*):
 * it dereferences the second argument. Guard small integer values so the
 * local test can report the invalid-pointer condition instead of crashing. */
static rsRetVal test_setter(void *pVal, uchar *pNewVal)
{
    (void)pVal;
    g_called++;
    g_ptr = pNewVal;
    if ((uintptr_t)pNewVal < 0x10000u) {
        g_invalid_ptr = 1;
        return RS_RET_OK;
    }
    g_char = *pNewVal;
    return RS_RET_OK;
}

int main(void)
{
    uchar buf[] = "Arest";
    uchar *p = buf;
    uchar *expected = p; /* no leading whitespace -> *pp is the config char */
    int failures = 0;
    rsRetVal r = doGetChar(&p, (HANDLER_T)test_setter, (void*)0);

    if (r != RS_RET_OK) {
        printf("FAIL: doGetChar returned %d\n", (int)r);
        failures++;
    }
    if (g_called != 1) {
        printf("FAIL: setter callback called %d times\n", g_called);
        failures++;
    }
    if (g_invalid_ptr) {
        printf("FAIL: setter received invalid pointer value %p (integer cast to pointer)\n",
               (void*)g_ptr);
        failures++;
    }
    if (g_ptr != expected) {
        printf("FAIL: setter pointer %p != expected *pp %p\n",
               (void*)g_ptr, (void*)expected);
        failures++;
    }
    if (!g_invalid_ptr && g_char != 'A') {
        printf("FAIL: setter dereferenced char 0x%02x, expected 0x41\n", g_char);
        failures++;
    }
    if (p != buf + 1) {
        printf("FAIL: *pp was not advanced past the consumed char\n");
        failures++;
    }

    if (failures == 0) {
        printf("PASS: setter received valid pointer to config char and *pp advanced\n");
        return 0;
    }
    return 1;
}
"""


def extract_function(source_text: str) -> tuple[str, str]:
    """Return (verbatim doGetChar definition, second-parameter type)."""
    m = SIG_RE.search(source_text)
    if not m:
        raise SystemExit("ERROR: doGetChar signature not found in source")
    arg_type = m.group(1).strip()
    start = m.start()
    i = source_text.index("{", m.end())
    depth = 0
    end = None
    for j in range(i, len(source_text)):
        ch = source_text[j]
        if ch == "{":
            depth += 1
        elif ch == "}":
            depth -= 1
            if depth == 0:
                end = j + 1
                break
    if end is None:
        raise SystemExit("ERROR: could not brace-match doGetChar body")
    return source_text[start:end], arg_type


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--source", required=True, help="path to runtime/cfsysline.c (or a checkout cwd)")
    ap.add_argument("--expect", choices=["fixed", "buggy"], required=True)
    ap.add_argument("--keep", action="store_true")
    args = ap.parse_args()

    src_path = Path(args.source)
    if not src_path.is_file():
        print(f"ERROR: source not found: {src_path}", file=sys.stderr)
        return 2
    source_text = src_path.read_text(encoding="utf-8", errors="replace")
    func, arg_type = extract_function(source_text)
    handler_t = f"rsRetVal (*)(void*, {arg_type})"
    program = PRELUDE + func + "\n" + EPILOGUE.replace("HANDLER_T", handler_t)

    with tempfile.TemporaryDirectory(prefix="dogetchar-") as tmp:
        tmpdir = Path(tmp)
        c_file = tmpdir / "harness.c"
        bin_file = tmpdir / "harness"
        c_file.write_text(program, encoding="utf-8")
        compile_cmd = ["gcc", "-O0", "-w", "-o", str(bin_file), str(c_file)]
        comp = subprocess.run(compile_cmd, capture_output=True, text=True)
        if comp.returncode != 0:
            print("COMPILE FAILED:\n" + comp.stdout + comp.stderr, file=sys.stderr)
            return 2
        run = subprocess.run([str(bin_file)], capture_output=True, text=True)
        print(f"source={src_path}")
        print(f"extracted_setter_arg_type={arg_type}")
        print(f"expect={args.expect} rc={run.returncode}")
        print(run.stdout.strip())
        if run.stderr.strip():
            print("stderr: " + run.stderr.strip())
        observed = "fixed" if run.returncode == 0 else "buggy"
        if observed != args.expect:
            print(f"RESULT: MISMATCH (expected {args.expect}, observed {observed})")
            return 1
        print(f"RESULT: MATCH ({observed})")
        return 0


if __name__ == "__main__":
